package com.facultyavailability.faculty_availability.controller;
import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import jakarta.servlet.http.HttpSession; import java.time.*; import com.facultyavailability.faculty_availability.entity.*; import com.facultyavailability.faculty_availability.repository.*;
@Controller public class PortalController {
 private final AppUserRepository users; private final FacultyAvailabilityRepository slots; private final AppointmentRepository appointments;
 public PortalController(AppUserRepository u,FacultyAvailabilityRepository s,AppointmentRepository a){users=u;slots=s;appointments=a;}
 private Long uid(HttpSession s){return (Long)s.getAttribute("userId");} private String role(HttpSession s){return (String)s.getAttribute("role");}
 @GetMapping("/student/dashboard") public String student(HttpSession s,Model m){if(uid(s)==null)return "redirect:/login";if(!"STUDENT".equals(role(s)))return "redirect:/dashboard";m.addAttribute("slots",slots.findByActiveTrueOrderByDateAscStartTimeAsc());m.addAttribute("appointments",appointments.findByStudentIdOrderByCreatedAtDesc(uid(s)));return "student";}
 @PostMapping("/student/book/{id}") public String book(@PathVariable Long id,@RequestParam String purpose,HttpSession s){if(uid(s)==null||!"STUDENT".equals(role(s)))return "redirect:/login";FacultyAvailability slot=slots.findById(id).orElseThrow();if(!slot.isActive()||slot.getDate().isBefore(LocalDate.now()))return "redirect:/student/dashboard?error";AppUser student=users.findById(uid(s)).orElseThrow();Appointment a=new Appointment();a.setStudent(student);a.setFaculty(slot.getFaculty());a.setAvailability(slot);a.setPurpose(purpose);appointments.save(a);return "redirect:/student/dashboard?booked";}
 @GetMapping("/faculty/dashboard") public String faculty(HttpSession s,Model m){if(uid(s)==null)return "redirect:/login";if(!"FACULTY".equals(role(s)))return "redirect:/dashboard";m.addAttribute("slots",slots.findByFacultyIdOrderByDateAscStartTimeAsc(uid(s)));m.addAttribute("appointments",appointments.findByFacultyIdOrderByCreatedAtDesc(uid(s)));return "faculty";}
 @PostMapping("/faculty/availability") public String addSlot(@RequestParam String date,@RequestParam String startTime,@RequestParam String endTime,@RequestParam(required=false) String location,@RequestParam(required=false) String note,HttpSession s){if(uid(s)==null||!"FACULTY".equals(role(s)))return "redirect:/login";LocalDate d=LocalDate.parse(date);LocalTime st=LocalTime.parse(startTime),en=LocalTime.parse(endTime);if(!d.isBefore(LocalDate.now())&&en.isAfter(st)){FacultyAvailability f=new FacultyAvailability();f.setFaculty(users.findById(uid(s)).orElseThrow());f.setDate(d);f.setStartTime(st);f.setEndTime(en);f.setLocation(location);f.setNote(note);slots.save(f);}return "redirect:/faculty/dashboard";}
 @PostMapping("/faculty/appointment/{id}") public String update(@PathVariable Long id,@RequestParam String status,HttpSession s){if(uid(s)==null||!"FACULTY".equals(role(s)))return "redirect:/login";Appointment a=appointments.findById(id).orElseThrow();if(a.getFaculty().getId().equals(uid(s))&&("APPROVED".equals(status)||"REJECTED".equals(status))) {a.setStatus(status);appointments.save(a);}return "redirect:/faculty/dashboard";}
 @GetMapping("/admin/dashboard") public String admin(HttpSession s,Model m){if(uid(s)==null||!"ADMIN".equals(role(s)))return "redirect:/login";m.addAttribute("users",users.findAll());m.addAttribute("appointments",appointments.findAll());return "admin";}
}
